mapper.sql:
ORDER BY i.created_at ASC, i.id ASC
    i.created_at DESC, i.id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.select:
SELECT i.comment_id FROM destination_comment_images i
JOIN destination_comments c ON c.id = i.comment_id
WHERE i.gallery_status = #{status} 
GROUP BY i.comment_id ORDER BY MAX(i.created_at) DESC, MAX(i.id) DESC
LIMIT #{limit} OFFSET #{offset}

mapper.sql:
((i.gallery_priority IS NULL) ${asc} #{anchor.priorityNull}
OR ((i.gallery_priority IS NULL) = #{anchor.priorityNull} AND (
    COALESCE(i.gallery_priority, 0) ${asc} #{anchor.priorityValue}
    OR (COALESCE(i.gallery_priority, 0) = #{anchor.priorityValue} AND (
        COALESCE(c.created_at, '1000-01-01 00:00:00') ${desc} #{anchor.reviewCreatedAt}
        OR (COALESCE(c.created_at, '1000-01-01 00:00:00') = #{anchor.reviewCreatedAt} AND (
            c.id ${desc} #{anchor.commentId}
            OR (c.id = #{anchor.commentId} AND (
                i.display_order ${asc} #{anchor.displayOrder}
                OR (i.display_order = #{anchor.displayOrder} AND i.id ${asc} #{anchor.imageId})
            ))
        ))
    ))
)))

mapper.update:
UPDATE destination_comment_images
SET gallery_status = #{status}, reviewed_by = #{adminId},
    reviewed_at = CURRENT_TIMESTAMP, review_reason = #{reason}

    , gallery_consent_withdrawn_at = CURRENT_TIMESTAMP

WHERE id = #{imageId}
